   if t in ['picked','r1','r2','r3'] and ts[i+1:i+2]==[':=']:
    j=i+2
    while ts[j] not in [';','end']:j+=1
    a.set(i,j-1,'r','record arrived information in problem-specific holding state')
   if t=='xa' and ts[i+1:i+2]==['[']:
    j=i+1
